namespace sv_73a424e16e624cebbb701af4e100f8e5.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_73a424e16e624cebbb701af4e100f8e5.Components.Pages.Settings
@using sv_73a424e16e624cebbb701af4e100f8e5.Services

<div class="profile-section">
    @if (_loading)
    {
        <div class="text-center p-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (_profile is not null)
    {
        <h4 class="section-title">Profile Settings</h4>

        @if (!string.IsNullOrEmpty(_successMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_successMessage
                <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
            </div>
        }

        <div class="profile-form">
            <div class="avatar-area mb-4">
                <div class="avatar-preview">
                    <img src="@_editDisplayAvatarUrl" alt="Avatar" class="avatar-img" />
                </div>
                <div class="avatar-url-display">
                    <small class="text-muted">Avatar URL:</small>
                    <code>@_editDisplayAvatarUrl</code>
                </div>
            </div>

            <div class="mb-3">
                <label class="form-label" for="displayName">Display Name</label>
                <input type="text" class="form-control" id="displayName" @bind="_editDisplayName" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="email">Email</label>
                <input type="email" class="form-control" id="email" @bind="_editEmail" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="bio">Bio</label>
                <textarea class="form-control" id="bio" rows="4" @bind="_editBio"></textarea>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@_saving">
                    Discard Changes
                </button>
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private UserProfile? _profile;
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editDisplayAvatarUrl = "";
    private string _editBio = "";

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        _loading = true;
        _profile = await SettingsService.GetProfileAsync();
        PopulateFields();
        _loading = false;
    }

    private void PopulateFields()
    {
        if (_profile is null) return;
        _editDisplayName = _profile.DisplayName;
        _editEmail = _profile.Email;
        _editDisplayAvatarUrl = _profile.AvatarUrl;
        _editBio = _profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;
        var updated = new UserProfile(_editDisplayName, _editEmail, _editDisplayAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _successMessage = "Profile saved successfully!";
        _saving = false;
    }

    private void DiscardChanges()
    {
        PopulateFields();
        _successMessage = null;
    }
}

.profile-section {
    padding: 1.5rem;
}

.section-title {
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid #dee2e6;
    flex-shrink: 0;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-url-display {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    min-width: 0;
}

.avatar-url-display code {
    word-break: break-all;
    font-size: 0.8rem;
}

