@namespace sv_73a424e16e624cebbb701af4e100f8e5.Components.Pages.Settings
@using sv_73a424e16e624cebbb701af4e100f8e5.Services

<div class="appearance-section">
    @if (_loading)
    {
        <div class="text-center p-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <h4 class="section-title">Appearance Settings</h4>

        @if (!string.IsNullOrEmpty(_successMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_successMessage
                <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
            </div>
        }

        <!-- Theme Selector -->
        <div class="mb-4">
            <h6>Theme</h6>
            <div class="d-flex gap-3">
                @foreach (var theme in _themes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               value="@theme" checked="@(_selectedTheme == theme)"
                               @onchange="() => _selectedTheme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="mb-4">
            <h6>Font Size</h6>
            <div class="d-flex gap-3">
                @foreach (var size in _fontSizes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                               value="@size" checked="@(_selectedFontSize == size)"
                               @onchange="() => _selectedFontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="mb-4">
            <h6>Language</h6>
            <select class="form-select" style="max-width: 300px;" @bind="_selectedLanguage">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                <label class="form-check-label" for="compactMode">
                    Compact Mode
                    <small class="d-block text-muted">Reduce spacing and padding throughout the UI</small>
                </label>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="preview-area mb-4">
            <h6>Preview</h6>
            <div class="preview-box @GetPreviewThemeClass()" style="@GetPreviewStyle()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">
                    This is how your content will look with the selected settings.
                    The theme is <strong>@_selectedTheme</strong>, font size is <strong>@_selectedFontSize</strong>,
                    and compact mode is <strong>@(_compactMode ? "on" : "off")</strong>.
                </p>
                <button class="preview-button">Sample Button</button>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private string _selectedTheme = "Light";
    private string _selectedFontSize = "Medium";
    private string _selectedLanguage = "English";
    private bool _compactMode;

    private static readonly string[] _themes = { "Light", "Dark", "System" };
    private static readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private static readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese" };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _selectedTheme = settings.Theme;
        _selectedFontSize = settings.FontSize;
        _selectedLanguage = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewThemeClass() => _selectedTheme switch
    {
        "Dark" => "preview-dark",
        "Light" => "preview-light",
        _ => "preview-system"
    };

    private string GetPreviewStyle()
    {
        var fontSize = _selectedFontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        var padding = _compactMode ? "0.75rem" : "1.5rem";
        return $"font-size: {fontSize}; padding: {padding};";
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;
        var settings = new AppearanceSettings(_selectedTheme, _selectedFontSize, _selectedLanguage, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _successMessage = "Appearance settings saved!";
        _saving = false;
    }
