.appearance-section {
    padding: 1.5rem;
}

.section-title {
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.preview-area .preview-box {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    transition: all 0.2s ease;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
}

.preview-system {
    background: #f8f9fa;
    color: #212529;
}

.preview-header {
    font-weight: 700;
    margin-bottom: 0.5rem;
    font-size: 1.1em;
}

.preview-text {
    margin-bottom: 0.75rem;
    line-height: 1.5;
}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 0.375rem;
    border: none;
    font-weight: 500;
    cursor: default;
}

.preview-light .preview-button {
    background: #0d6efd;
    color: #fff;
}

.preview-dark .preview-button {
    background: #6ea8fe;
    color: #1e1e2e;
}

.preview-system .preview-button {
    background: #0d6efd;
    color: #fff;
}

